"""Related rates: source-based statements, explicit models and signed rates."""
import json,math,sys
import sympy as s
import mpmath as mp
from early_helpers import Book,pair,same,fs,ROOT
b=Book('2.8',[189,190,191,192]);checks=[];mp.mp.dps=40
M=lambda v:r'\('+v+r'\)'
def add(n,eq,k,e,lines,ans,parts='',note=None):
 pg=189 if n<=16 else 190 if n<=31 else 191 if n<=47 else 192
 steps=fs(*lines)
 if note:steps.append(note)
 b.add(n,pg,('관련 변화율','Related rates'),(M(eq)+' '+k,M(eq)+' '+e),steps,same(M(ans)),parts=list(parts),hint=('변수 사이의 관계를 먼저 세우고 시간으로 미분한 다음 순간값을 대입한다.','Relate the changing variables, differentiate with respect to time, then substitute the instantaneous values.'),check=('관계식의 시간 미분, 변화 방향과 단위를 대조했다.','Checked the time derivative of the relation, the direction of change and the units.'))
 b.E[n]['conceptHref']='../../calc1/index.html'
add(1,r'V=x^3','팽창하는 정육면체의 (a) 부피 변화율 공식을 구하고 (b) 모서리가 십오 센티미터이며 초당 사 센티미터 증가할 때 계산하라.','For an expanding cube, (a) express the volume rate using the edge rate and (b) evaluate at edge 15 cm increasing at 4 cm/s.',[r'\dot V=3x^2\dot x',r'\dot V=3(15)^2(4)'],r'\text{(a)}\dot V=3x^2\dot x;\quad\text{(b)}\ 2700\ \mathrm{cm^3/s}',parts='ab')
add(2,r'A=\pi r^2','(a) 원의 넓이 변화율을 구하고 (b) 원형 기름띠 반지름이 초당 이 미터 증가하며 삼십 미터일 때 계산하라.','(a) Relate area rate to radius rate; (b) evaluate for a circular oil slick with radius 30 m expanding at 2 m/s.',[r'\dot A=2\pi r\dot r',r'\dot A=2\pi(30)(2)'],r'\text{(a)}\dot A=2\pi r\dot r;\quad\text{(b)}\ 120\pi\ \mathrm{m^2/s}',parts='ab')
add(3,r'\dot x=6\ \mathrm{cm/s},\quad A=16\ \mathrm{cm^2}','정사각형의 넓이 증가율을 구하라.','Find the square’s area growth rate.',[r'A=x^2\Rightarrow x=4',r'\dot A=2x\dot x=2(4)(6)'],r'48\ \mathrm{cm^2/s}')
add(4,r'\dot r=4\ \mathrm{mm/s},\quad 2r=80\ \mathrm{mm}','구의 부피 증가율을 구하라.','Find the sphere’s volume growth rate.',[r'V=4\pi r^3/3,\quad r=40',r'\dot V=4\pi r^2\dot r=4\pi(40)^2(4)'],r'25600\pi\ \mathrm{mm^3/s}')
add(5,r'\dot r=2\ \mathrm{cm/min},\quad r=8\ \mathrm{cm}','구의 겉넓이 증가율을 구하라.','Find the sphere’s surface-area growth rate.',[r'S=4\pi r^2,\quad\dot S=8\pi r\dot r',r'\dot S=8\pi(8)(2)'],r'128\pi\ \mathrm{cm^2/min}')
add(6,r'\dot l=8,\quad\dot w=3\ (\mathrm{cm/s});\quad l=20,\ w=10\ (\mathrm{cm})','직사각형의 넓이 증가율을 구하라.','Find the rectangle’s area growth rate.',[r'A=lw,\quad\dot A=w\dot l+l\dot w',r'\dot A=10(8)+20(3)'],r'140\ \mathrm{cm^2/s}')
add(7,r'r=5\ \mathrm m,\quad\dot V=3\ \mathrm{m^3/min}','원기둥 수조의 수위 상승률을 구하라.','Find the water-level rise rate in a cylindrical tank.',[r'V=\pi r^2h=25\pi h',r'3=25\pi\dot h'],r'\dot h=3/(25\pi)\ \mathrm{m/min}')
add(8,r'A=\tfrac12ab\sin\theta,\quad a=2,\ b=3,\ \theta=\pi/3','길이는 센티미터, 시간은 분이다. 각속도는 영점이 라디안/분이다. (a) 두 변 고정, (b) a 고정·b가 분당 일점오 증가, (c) a도 분당 이점오 증가할 때 넓이 변화율을 구하라.','Lengths are in cm and time in minutes; the angle increases at 0.2 rad/min. Find area rates when (a) both sides are fixed, (b) a is fixed and b grows at 1.5 cm/min, (c) a also grows at 2.5 cm/min.',[r'\dot A=\tfrac12[(b\dot a+a\dot b)\sin\theta+ab\cos\theta\dot\theta]',r'\text{(a)}\dot A=\tfrac12(6)(1/2)(1/5)=3/10',r'\text{(b)}\dot A=3\sqrt3/4+3/10',r'\text{(c)}\dot A=21\sqrt3/8+3/10'],r'\text{(a)}\frac3{10};\quad\text{(b)}\frac{3\sqrt3}4+\frac3{10};\quad\text{(c)}\frac{21\sqrt3}8+\frac3{10}\quad(\mathrm{cm^2/min})',parts='abc')
add(9,r'4x^2+9y^2=25','(a) (2,1)에서 ẏ=1/3일 때 ẋ, (b) (−2,1)에서 ẋ=3일 때 ẏ를 구하라.','(a) Find ẋ at (2,1) when ẏ=1/3; (b) find ẏ at (−2,1) when ẋ=3.',[r'8x\dot x+18y\dot y=0',r'\text{(a)}\ 16\dot x+6=0',r'\text{(b)}\ -48+18\dot y=0'],r'\text{(a)}\dot x=-3/8;\quad\text{(b)}\dot y=8/3',parts='ab')
add(10,r'x^2+y^2+z^2=9,\quad\dot x=5,\quad\dot y=4,\quad(x,y,z)=(2,2,1)','z의 시간 변화율을 구하라.','Find the time derivative of z.',[r'x\dot x+y\dot y+z\dot z=0',r'\dot z=-(2\cdot5+2\cdot4)/1'],r'\dot z=-18')
add(11,r'w=130\left(\frac{3960}{3960+h}\right)^2,\quad\dot h=12\ \mathrm{mi/s},\ h=40\ \mathrm{mi}','지표면에서 백삼십 파운드인 우주비행사의 무게 변화율을 구하라.','Find the weight-change rate for an astronaut whose surface weight is 130 lb.',[r'\dot w=-\frac{260(3960)^2}{(3960+h)^3}\dot h',r'\dot w=-\frac{260(3960)^2(12)}{4000^3}'],r'\dot w=-0.764478\ \mathrm{lb/s}')
add(12,r'xy=8,\quad(x,y)=(4,2),\quad\dot y=-3\ \mathrm{cm/s}','움직이는 점의 x좌표 변화율을 구하라.','Find the moving point’s x-coordinate rate.',[r'y\dot x+x\dot y=0',r'2\dot x+4(-3)=0'],r'\dot x=6\ \mathrm{cm/s}')
add(13,r'h=1\ \mathrm{mi},\quad\dot x=500\ \mathrm{mi/h},\quad s=2\ \mathrm{mi}','비행기가 레이더 위를 지나 수평으로 멀어진다. (a) 주어진 값, (b) 미지수, (c) 도형, (d) 관계식을 정리하고 (e) 직선거리 변화율을 구하라.','A plane moves horizontally away after passing over radar. Identify (a) data, (b) unknown, (c) geometry, (d) relation and (e) the slant-distance rate.',[r'\text{(a)}\ h=1,\ \dot x=500,\ s=2;\quad\text{(b)}\dot s',r'\text{(c)}\text{right triangle: horizontal }x,\text{ vertical }1,\text{ hypotenuse }s',r'\text{(d)}\quad s^2=x^2+1\Rightarrow s\dot s=x\dot x',r'\text{(e)}\quad x=\sqrt3,\quad\dot s=500\sqrt3/2'],r'\dot s=250\sqrt3\ \mathrm{mi/h}',parts='abcde')
add(14,r'\dot S=-1\ \mathrm{cm^2/min},\quad D=10\ \mathrm{cm}','녹는 구형 눈덩이의 (a) 주어진 값, (b) 미지수, (c) 도형, (d) 관계식을 정리하고 (e) 지름 감소율을 구하라.','For a melting spherical snowball, identify (a) data, (b) unknown, (c) geometry, (d) relation and (e) diameter decrease rate.',[r'\text{(a)}\dot S=-1,\ D=10;\quad\text{(b)}\dot D',r'\text{(c)}\text{sphere with radius }D/2',r'\text{(d)}\quad S=4\pi(D/2)^2=\pi D^2',r'\text{(e)}\dot S=2\pi D\dot D\Rightarrow\dot D=-1/(20\pi)'],r'\dot D=-1/(20\pi)\ \mathrm{cm/min}',parts='abcde')
add(15,r'H=15\ \mathrm{ft},\quad h=6\ \mathrm{ft},\quad\dot x=5\ \mathrm{ft/s},\quad x=40\ \mathrm{ft}','가로등에서 멀어지는 사람의 그림자 끝 속도를 구하라. (a) 주어진 값, (b) 미지수, (c) 도형, (d) 관계식, (e) 계산을 제시하라.','Find the shadow-tip speed for a person walking away from the lamp. Give (a) data, (b) unknown, (c) diagram, (d) relation and (e) calculation.',[r'\text{(a)}\quad H=15,h=6,\dot x=5;\quad\text{(b)}\dot z,\ z=x+y',r'\text{(c)}\text{similar triangles: lamp height }15,\text{ person height }6,\text{ shadow }y',r'\text{(d)}\ 15/(x+y)=6/y\Rightarrow y=2x/3',r'\text{(e)}\quad z=5x/3\Rightarrow\dot z=25/3'],r'\dot z=25/3\ \mathrm{ft/s}',parts='abcde')
add(16,r'A(0)=(-150,0),\ B(0)=(0,0)\ \mathrm{km};\quad v_A=(35,0),\ v_B=(0,25)\ \mathrm{km/h}','정오부터 네 시간 후 두 배의 거리 변화율을 구하라. (a) 자료, (b) 미지수, (c) 도형, (d) 관계식과 (e) 계산을 제시하라.','Find the separation rate four hours after noon, giving (a) data, (b) unknown, (c) diagram, (d) relation and (e) calculation.',[r'\text{(a)}\ t=4;\quad\text{(b)}\dot s',r'\text{(c)}\quad x=150-35t,\quad y=25t\quad\text{(right-triangle legs)}',r'\text{(d)}\quad s^2=x^2+y^2\Rightarrow s\dot s=x(-35)+y(25)',r'\text{(e)}\quad x=10,\ y=100,\ s=10\sqrt{101}'],r'\dot s=215/\sqrt{101}\ \mathrm{km/h}',parts='abcde')
add(17,r'v_1=60\ \mathrm{mi/h}\text{ south},\quad v_2=25\ \mathrm{mi/h}\text{ west}','같은 점에서 출발한 두 차의 두 시간 후 거리 증가율을 구하라.','Two cars leave one point simultaneously. Find their separation rate two hours later.',[r's^2=(60t)^2+(25t)^2=4225t^2',r's=65t\quad(t>0)'],r'\dot s=65\ \mathrm{mi/h}')
add(18,r'\text{light-wall distance}=12\ \mathrm m,\quad\text{person height}=2\ \mathrm m','사람이 지면의 조명에서 벽으로 초당 일점육 미터로 걷는다. 벽까지 사 미터일 때 벽 그림자 높이의 감소율을 구하라.','A person walks from a ground spotlight toward the wall at 1.6 m/s. Find the shadow-height decrease rate when the person is 4 m from the wall.',[r'x=\text{distance from light},\quad x=8,\quad\dot x=1.6',r'y/12=2/x\Rightarrow y=24/x',r'\dot y=-24\dot x/x^2=-24(1.6)/64'],r'\dot y=-0.6\ \mathrm{m/s}')
add(19,r'v_m=4\ \mathrm{ft/s}\text{ north},\quad v_w=5\ \mathrm{ft/s}\text{ south}','남자가 P에서 출발하고 오 분 뒤 여자가 P의 동쪽 오백 피트 지점에서 출발한다. 여자 출발 십오 분 후 두 사람의 거리 증가율을 구하라.','A man leaves P; five minutes later a woman leaves a point 500 ft east of P. Find their separation rate fifteen minutes after she starts.',[r't=\text{seconds since woman starts},\quad y=4(t+300)+5t',r't=900:\quad y=9300,\quad\dot y=9',r's^2=500^2+y^2\Rightarrow\dot s=y\dot y/\sqrt{500^2+y^2}'],r'\dot s=837/\sqrt{8674}\ \mathrm{ft/s}')
add(20,r'\text{diamond side}=90\ \mathrm{ft},\quad\dot x=24\ \mathrm{ft/s},\quad x=45\ \mathrm{ft}','타자가 홈에서 일루로 달린다. 중간 지점에서 (a) 이루까지 거리의 감소율과 (b) 삼루까지 거리의 증가율을 구하라.','A batter runs from home to first. Halfway there, find (a) the decrease rate of distance to second and (b) increase rate of distance to third.',[r's_2^2=(90-x)^2+90^2,\quad s_3^2=x^2+90^2',r'\dot s_2=-(90-x)\dot x/s_2,\quad\dot s_3=x\dot x/s_3',r's_2=s_3=45\sqrt5'],r'\text{(a)}\dot s_2=-24/\sqrt5;\quad\text{(b)}\dot s_3=24/\sqrt5\quad(\mathrm{ft/s})',parts='ab')
add(21,r'\dot h=1\ \mathrm{cm/min},\quad\dot A=2\ \mathrm{cm^2/min},\quad h=10\ \mathrm{cm},\quad A=100\ \mathrm{cm^2}','삼각형 밑변의 변화율을 구하라.','Find the triangle’s base-length rate.',[r'A=bh/2\Rightarrow b=20',r'2\dot A=h\dot b+b\dot h',r'4=10\dot b+20'],r'\dot b=-8/5\ \mathrm{cm/min}')
add(22,r'\text{pulley height above bow}=1\ \mathrm m,\quad\dot l=-1\ \mathrm{m/s},\quad x=8\ \mathrm m','밧줄로 부두 쪽으로 당기는 배의 수평 접근 속력을 구하라.','Find the horizontal approach speed of a boat pulled toward the dock.',[r'l^2=x^2+1,\quad l=\sqrt{65}',r'l\dot l=x\dot x\Rightarrow\dot x=-\sqrt{65}/8'],r'\text{approach speed}=\sqrt{65}/8\ \mathrm{m/s}')
add(23,r'd=4.9t^2\ \mathrm m','절벽의 같은 곳에서 돌 두 개를 일 초 간격으로 놓는다. 둘째 돌을 놓은 지 일 초 뒤 돌 사이 거리 변화율을 구하라.','Drop two stones from the same cliff point one second apart. Find their separation rate one second after the second release.',[r'z=4.9[t^2-(t-1)^2]=9.8t-4.9\quad(t\ge1)',r'\dot z=9.8'],r'9.8\ \mathrm{m/s}')
add(24,r'd=4.9t^2\ \mathrm m,\quad\text{horizontal separation}=10\ \mathrm m','같은 높이에서 십 미터 떨어진 두 사람이 일 초 간격으로 돌을 놓는다. 둘째 돌을 놓은 지 일 초 후 돌 사이 거리 변화율을 구하라.','Two people at equal elevation and 10 m apart release stones one second apart. Find the separation rate one second after the second release.',[r'z=4.9[t^2-(t-1)^2],\quad t=2\Rightarrow z=14.7,\ \dot z=9.8',r's^2=100+z^2,\quad\dot s=z\dot z/s'],r'\dot s=144.06/\sqrt{316.09}\ \mathrm{m/s}\approx8.10285\ \mathrm{m/s}')
add(25,r'H=600\ \mathrm{cm},\quad R=200\ \mathrm{cm},\quad h=200\ \mathrm{cm},\quad\dot h=20\ \mathrm{cm/min}','거꾸로 선 원뿔 수조에서 분당 만 세제곱센티미터가 새고 있다. 유입량을 구하라.','An inverted conical tank leaks at 10,000 cm³/min. Find the inflow rate.',[r'r/h=R/H=1/3,\quad V=\pi h^3/27',r'\dot V=\pi h^2\dot h/9=800000\pi/9',r'\dot V=Q_{\rm in}-10000'],r'Q_{\rm in}=10000+800000\pi/9\ \mathrm{cm^3/min}')
add(26,r'y=2\sin(\pi x/2),\quad(x,y)=(1/3,1),\quad\dot x=\sqrt{10}\ \mathrm{cm/s}','움직이는 점과 원점 사이 거리 변화율을 구하라.','Find the rate of change of distance from the moving point to the origin.',[r'\dot y=\pi\cos(\pi x/2)\dot x=\pi\sqrt{30}/2',r's^2=x^2+y^2,\quad s=\sqrt{10}/3',r'\dot s=(x\dot x+y\dot y)/s'],r'\dot s=1+3\pi\sqrt3/2\ \mathrm{cm/s}')
add(27,r'L=10\ \mathrm m,\ b=0.30\ \mathrm m,\ B=0.80\ \mathrm m,\ H=0.50\ \mathrm m','등변사다리꼴 단면 수로에 분당 영점이 세제곱미터가 유입된다. 깊이 영점삼 미터에서 수위 상승률을 구하라.','A trough with isosceles trapezoidal ends fills at 0.2 m³/min. Find the rise rate at depth 0.30 m.',[r'w(h)=0.30+(0.80-0.30)h/0.50=0.30+h',r'V=10\cdot\tfrac12(0.30+w)h=3h+5h^2',r'\dot V=(3+10h)\dot h,\quad0.2=6\dot h'],r'\dot h=1/30\ \mathrm{m/min}')
add(28,r'L=10\ \mathrm{ft},\quad B=3\ \mathrm{ft},\quad H=1\ \mathrm{ft},\quad\dot V=12\ \mathrm{ft^3/min}','등변삼각형 단면 수로의 물 깊이가 육 인치일 때 수위 상승률을 구하라.','Find the water-level rise rate in a triangular trough when the depth is six inches.',[r'h=0.5\ \mathrm{ft},\quad w=3h',r'V=10(wh/2)=15h^2',r'12=30h\dot h=15\dot h'],r'\dot h=4/5\ \mathrm{ft/min}')
add(29,r'\dot V=30\ \mathrm{ft^3/min},\quad 2r=h,\quad h=10\ \mathrm{ft}','원뿔 모양 자갈더미의 높이 증가율을 구하라.','Find the height growth rate of a conical gravel pile.',[r'V=\pi r^2h/3=\pi h^3/12',r'\dot V=\pi h^2\dot h/4',r'30=25\pi\dot h'],r'\dot h=6/(5\pi)\ \mathrm{ft/min}')
add(30,r'\text{pool width}=20\ \mathrm{ft},\quad\dot V=0.8\ \mathrm{ft^3/min}','길이 사십 피트 수영장의 종단면은 깊은 바닥 길이 십이 피트, 왼쪽 경사 수평 육·수직 육 피트, 오른쪽 경사 수평 십육·수직 육 피트, 얕은 바닥 육 피트로 이루어진다. 최대 깊이는 구 피트, 얕은 곳은 삼 피트이다. 깊은 곳 물높이가 오 피트일 때 수위 상승률을 구하라.','The 40-ft longitudinal section has a 12-ft deep flat bottom, a left slope rising 6 ft over 6 horizontal ft, a right slope rising 6 ft over 16 horizontal ft, and a 6-ft shallow shelf. Maximum and shallow depths are 9 and 3 ft. Find the rise rate when deep-end water depth is 5 ft.',[r'0<h<6:\quad\text{surface length}=12+h+(16/6)h=12+11h/3',r'V=20(12h+11h^2/6)',r'\dot V=20(12+11h/3)\dot h',r'0.8=(1820/3)\dot h'],r'\dot h=3/2275\ \mathrm{ft/min}')
add(31,r'\dot a=10\ \mathrm{cm/min},\quad a=30\ \mathrm{cm}','정삼각형의 넓이 증가율을 구하라.','Find the equilateral triangle’s area growth rate.',[r'A=\sqrt3 a^2/4',r'\dot A=(\sqrt3/2)a\dot a'],r'150\sqrt3\ \mathrm{cm^2/min}')
add(32,r'y=100\ \mathrm{ft},\quad\dot x=8\ \mathrm{ft/s},\quad s=200\ \mathrm{ft}','일정 높이에서 수평으로 멀어지는 연의 줄과 수평선 사이 각의 감소율을 구하라.','Find the decrease rate of the string’s angle to the horizontal as a kite moves away at constant altitude.',[r'\tan\theta=100/x,\quad\sec^2\theta\dot\theta=-100\dot x/x^2',r'\dot\theta=-100\dot x/(x^2+100^2)=-800/200^2'],r'\dot\theta=-0.02\ \mathrm{rad/s}')
add(33,r'v_c=20\ \mathrm{m/s}\text{ north},\quad v_d=6\ \mathrm{m/s}\text{ east},\quad h=25\ \mathrm m','드론이 차의 바로 위를 지난 뒤 오 초 후 둘 사이 거리 변화율을 구하라.','Find the separation rate five seconds after the drone passes directly above the car.',[r's^2=(20t)^2+(6t)^2+25^2=436t^2+625',r's\dot s=436t',r't=5:\quad s=5\sqrt{461}'],r'\dot s=436/\sqrt{461}\ \mathrm{m/s}')
add(34,r'\text{minute-hand length}=r\ \mathrm{cm}','분침이 쓸고 지나가는 부채꼴 넓이의 시간 증가율을 구하라.','Find the rate at which a clock’s minute hand sweeps out area.',[r'A=\tfrac12r^2\theta,\quad\dot\theta=2\pi/60=\pi/30\ \mathrm{rad/min}',r'\dot A=\tfrac12r^2\dot\theta'],r'\dot A=\pi r^2/60\ \mathrm{cm^2/min}')
add(35,r'L=10\ \mathrm{ft},\quad\dot x=4\ \mathrm{ft/s},\quad x=6\ \mathrm{ft}','벽에 기대어 미끄러지는 사다리와 지면 사이 각의 변화율을 구하라.','Find the angle rate between the ground and a ladder whose base slides away from the wall.',[r'x=10\cos\theta,\quad\dot x=-10\sin\theta\dot\theta',r'y=\sqrt{100-36}=8\Rightarrow\sin\theta=4/5',r'4=-8\dot\theta'],r'\dot\theta=-1/2\ \mathrm{rad/s}')
add(36,r'x^2+y^2=100,\quad\dot x=4\ \mathrm{ft/s}','같은 사다리 모형에서 꼭대기가 지면에 다가갈 때의 속도를 분석하고, 아주 작은 높이에서 모형이 적절한지 설명하라.','For the same ladder model, analyze the top speed near the ground and discuss the model’s suitability at very small heights.',[r'\dot y=-x\dot x/y=-4\sqrt{100-y^2}/y',r'y\to0^+\Rightarrow\dot y\to-\infty'],r'\dot y\to-\infty',note=('항상 벽에 닿은 채 밑부분이 일정 속도로 움직인다는 가정은 지면 근방에서 무한 속도를 요구한다. 실제 사다리의 접촉과 가속 운동을 설명하려면 이 가정을 수정해야 한다.','Maintaining wall contact while the base keeps a fixed speed demands unbounded speed near the ground. A physical model must revise these assumptions to account for contact and acceleration.'))
add(37,r'PV=C,\quad V=600\ \mathrm{cm^3},\quad P=150\ \mathrm{kPa},\quad\dot P=20\ \mathrm{kPa/min}','등온 기체의 부피 감소율을 구하라.','Find the volume decrease rate for an isothermal gas.',[r'P\dot V+V\dot P=0',r'\dot V=-600(20)/150'],r'\dot V=-80\ \mathrm{cm^3/min}')
h=mp.findroot(lambda z:30*z*z-z**3/3-9000,20);rate=2000/(mp.pi*(60*h-h*h))
add(38,r'r=30\ \mathrm{cm},\quad\dot V=2000\ \mathrm{cm^3/min},\quad V=\pi(rh^2-h^3/3)','반구형 그릇이 부피의 절반만큼 찼을 때 수위 상승률을 구하라.','Find the rise rate when a hemispherical basin is half full by volume.',[r'V_{\rm full}=2\pi r^3/3=18000\pi,\quad V=9000\pi',r'30h^2-h^3/3=9000\Rightarrow h\approx'+f'{float(h):.10f}',r'\dot V=\pi(60h-h^2)\dot h'],r'\dot h\approx'+f'{float(rate):.10f}'+r'\ \mathrm{cm/min}',note=('절반 부피는 반지름의 절반 높이와 다르다. 깊이는 영과 삼십 사이의 유일한 해를 사용한다.','Half the volume does not mean half the radius in water depth. Use the unique height between zero and thirty.'));checks.append([38,str(h),str(rate)])
add(39,r'1/R=1/R_1+1/R_2,\quad R_1=80,\ R_2=100\ (\Omega),\quad\dot R_1=0.3,\ \dot R_2=0.2\ (\Omega/\mathrm s)','병렬 합성저항의 변화율을 구하라.','Find the rate of change of the parallel equivalent resistance.',[r'R=R_1R_2/(R_1+R_2)=400/9',r'-\dot R/R^2=-\dot R_1/R_1^2-\dot R_2/R_2^2',r'\dot R=(400/9)^2(0.3/80^2+0.2/100^2)'],r'\dot R=107/810\ \Omega/\mathrm s')
add(40,r'PV^{1.4}=C,\quad V=400\ \mathrm{cm^3},\quad P=80\ \mathrm{kPa},\quad\dot P=-10\ \mathrm{kPa/min}','단열 팽창하는 기체의 부피 증가율을 구하라.','Find the gas volume growth rate during adiabatic expansion.',[r'V^{1.4}\dot P+1.4PV^{0.4}\dot V=0',r'\dot V=-V\dot P/(1.4P)=4000/112'],r'\dot V=250/7\ \mathrm{cm^3/min}')
add(41,r'\theta=60^\circ,\quad v_1=40,\ v_2=60\ (\mathrm{mi/h})','육십 도로 갈라진 도로를 따라 같은 교차점에서 동시에 출발한 차들의 삼십 분 후 거리 증가율을 구하라.','Cars leave an intersection simultaneously along roads separated by sixty degrees. Find the separation rate after half an hour.',[r's^2=(40t)^2+(60t)^2-2(40t)(60t)\cos(\pi/3)',r's=20\sqrt7\,t\quad(t>0)'],r'\dot s=20\sqrt7\ \mathrm{mi/h}')
val=s.Rational(7,1000)*s.Rational(12,100)**s.Rational(2,3)*s.Rational(253,150)*18**s.Rational(103,150)*s.Rational(1,2000000)
add(42,r'B=0.007W^{2/3},\quad W=0.12L^{2.53}','어류의 무게와 뇌 무게는 그램, 길이는 센티미터이다. 천만 년에 걸쳐 평균 길이가 십오에서 이십으로 일정하게 증가할 때 길이 십팔에서 뇌 무게의 증가율을 구하라.','Body and brain weights are in grams and length is in cm. Mean length grows uniformly from 15 to 20 over ten million years. Find the brain-weight rate at length 18.',[r'\dot L=5/10^7\ \mathrm{cm/year}',r'B=0.007(0.12)^{2/3}L^{253/150}',r'\dot B=0.007(0.12)^{2/3}\frac{253}{150}L^{103/150}\dot L'],r'\dot B\approx'+f'{float(val):.10g}'+r'\ \mathrm{g/year}')
add(43,r'a=12\ \mathrm m,\quad b=15\ \mathrm m,\quad\dot\theta=2^\circ/\mathrm{min},\quad\theta=60^\circ','고정된 두 변 사이 각이 증가할 때 맞은편 변의 증가율을 구하라.','Find the third-side growth rate as the included angle between the fixed sides increases.',[r'c^2=12^2+15^2-360\cos\theta,\quad c=3\sqrt{21}',r'2c\dot c=360\sin\theta\dot\theta,\quad\dot\theta=\pi/90'],r'\dot c=\pi/(3\sqrt7)\ \mathrm{m/min}')
add(44,r'\text{rope length}=39\ \mathrm{ft},\quad\text{pulley height}=12\ \mathrm{ft},\quad x=5\ \mathrm{ft},\quad\dot x=2\ \mathrm{ft/s}','두 수레가 도르래 바로 아래 점 Q의 양쪽에 있다. A가 Q에서 멀어질 때 B가 Q로 접근하는 속력을 구하라.','Carts are on opposite sides of Q directly below a pulley. A moves away from Q. Find B’s approach speed.',[r'\sqrt{x^2+144}+\sqrt{y^2+144}=39',r'x=5\Rightarrow l_A=13,\ l_B=26,\ y=\sqrt{26^2-144}=2\sqrt{133}',r'\frac{x\dot x}{l_A}+\frac{y\dot y}{l_B}=0\Rightarrow\dot y=-10/\sqrt{133}'],r'\text{approach speed}=10/\sqrt{133}\ \mathrm{ft/s}')
add(45,r'x=4000\ \mathrm{ft},\quad h=3000\ \mathrm{ft},\quad\dot h=600\ \mathrm{ft/s}','카메라는 수직 상승 로켓의 발사대에서 수평 사천 피트 떨어져 있다. (a) 로켓까지 거리와 (b) 고도각의 변화율을 구하라.','A camera tracks a vertically rising rocket from 4000 ft horizontally away. Find rates of (a) camera-to-rocket distance and (b) elevation angle.',[r's^2=4000^2+h^2,\quad s=5000,\quad\dot s=h\dot h/s=360',r'\tan\theta=h/4000,\quad\dot\theta=4000\dot h/(4000^2+h^2)=0.096'],r'\text{(a)}\ 360\ \mathrm{ft/s};\quad\text{(b)}\ 0.096\ \mathrm{rad/s}',parts='ab')
add(46,r'd=3\ \mathrm{km},\quad\dot\theta=4\ \mathrm{rev/min},\quad x=1\ \mathrm{km}','등대는 직선 해안의 가장 가까운 점 P에서 삼 킬로미터 떨어져 있다. 빛이 P에서 일 킬로미터인 곳을 지날 때 해안을 따라 움직이는 속력을 구하라.','A lighthouse is 3 km from the nearest shore point P. Find the spot’s speed along the straight shore at distance 1 km from P.',[r'x=3\tan\theta,\quad\sec^2\theta=1+(x/3)^2=10/9',r'|\dot\theta|=8\pi\ \mathrm{rad/min},\quad|\dot x|=3\sec^2\theta|\dot\theta|'],r'|\dot x|=80\pi/3\ \mathrm{km/min}')
add(47,r'h=5\ \mathrm{km},\quad\theta=\pi/3,\quad\dot\theta=-\pi/6\ \mathrm{rad/min}','수평으로 비행하는 비행기가 지상 망원경 위를 지난 뒤의 속력을 구하라.','Find the horizontal speed of a plane after it passes over a ground telescope.',[r'x=5\cot\theta',r'\dot x=-5\csc^2\theta\dot\theta=-5(4/3)(-\pi/6)'],r'\dot x=10\pi/9\ \mathrm{km/min}')
add(48,r'r=10\ \mathrm m,\quad T=2\ \mathrm{min},\quad y=16\ \mathrm m','관람차 최저점이 지면에 있다고 가정하라. 좌석이 상승하는 순간의 수직 속력을 구하라.','Assume the lowest seat is at ground level. Find vertical speed on the rising part of the wheel.',[r'y=10+10\sin\theta,\quad|\dot\theta|=2\pi/2=\pi',r'\sin\theta=0.6\Rightarrow |\cos\theta|=0.8',r'\dot y=10\cos\theta\dot\theta'],r'\dot y=8\pi\ \mathrm{m/min}\quad\text{(rising)}',note=('같은 높이의 하강 지점에서는 부호가 반대다. 중심 높이가 다르면 주어진 높이에서의 답도 달라진다.','At the descending point of the same height the sign is reversed. A different center height changes the answer at the stated elevation.'))
add(49,r'v=300\ \mathrm{km/h},\quad\theta=30^\circ,\quad h(0)=1\ \mathrm{km}','비행기가 레이더 바로 위를 지나 일정한 각도로 상승한다. 일 분 후 레이더까지 거리 증가율을 구하라.','A plane passes directly above radar and climbs at a fixed angle. Find the radar-distance rate one minute later.',[r'x=300t\cos(\pi/6)=150\sqrt3\,t,\quad y=1+150t',r't=1/60:\quad x=5\sqrt3/2,\ y=7/2,\ s=\sqrt{31}',r'\dot s=(x\dot x+y\dot y)/s=(1125+525)/\sqrt{31}'],r'\dot s=1650/\sqrt{31}\ \mathrm{km/h}')
add(50,r'v_1=3\ \mathrm{mi/h}\text{ east},\quad v_2=2\ \mathrm{mi/h}\text{ northeast}','같은 점에서 출발하는 두 사람의 십오 분 후 거리 증가율을 구하라.','Find the separation rate fifteen minutes after two walkers leave the same point.',[r'\Delta x=(3-\sqrt2)t,\quad\Delta y=-\sqrt2\,t',r's=t\sqrt{(3-\sqrt2)^2+2}=t\sqrt{13-6\sqrt2}\quad(t>0)'],r'\dot s=\sqrt{13-6\sqrt2}\ \mathrm{mi/h}')
add(51,r'r=100\ \mathrm m,\quad OF=200\ \mathrm m,\quad v=7\ \mathrm{m/s},\quad s=200\ \mathrm m','원형 트랙을 달리는 사람과 중심에서 이백 미터 떨어져 서 있는 친구 사이 거리의 변화율을 구하라.','Find the separation rate between a circular-track runner and a stationary friend 200 m from the center.',[r's^2=100^2+200^2-40000\cos\theta',r's=200\Rightarrow\cos\theta=1/4,\quad |\sin\theta|=\sqrt{15}/4',r'|\dot\theta|=7/100,\quad\dot s=20000\sin\theta\dot\theta/s'],r'\dot s=\pm7\sqrt{15}/4\ \mathrm{m/s}',note=('달리는 방향과 위치가 지정되지 않았으므로 멀어질 때 양수, 가까워질 때 음수이며 속력의 크기는 같다.','Direction and position do not fix the sign: positive while separating and negative while approaching, with the same magnitude.'))
add(52,r'r_m=8\ \mathrm{mm},\quad r_h=4\ \mathrm{mm}','한 시 정각에서 시곗바늘 끝 사이 거리의 변화율을 구하라.','Find the rate of change of the tip-to-tip distance at one o’clock.',[r'\theta=\pi/6,\quad\dot\theta=\pi/360-\pi/30=-11\pi/360\ \mathrm{rad/min}',r's^2=8^2+4^2-64\cos\theta=80-32\sqrt3',r'2s\dot s=64\sin\theta\dot\theta'],r'\dot s=-11\pi/(90\sqrt{5-2\sqrt3})\ \mathrm{mm/min}')
add(53,r'\dot V=kS,\quad k>0\text{ constant}','구형 눈덩이의 부피 증가율이 겉넓이에 비례하면 반지름이 일정한 비율로 증가함을 보여라.','Show that a spherical snowball’s radius grows at a constant rate when its volume growth rate is proportional to surface area.',[r'V=4\pi r^3/3,\quad S=4\pi r^2',r'\dot V=4\pi r^2\dot r=k4\pi r^2',r'r>0\Rightarrow\dot r=k'],r'\dot r=k')
